<?php
$esc = function ($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); };
$types = array('Strength', 'Weakness', 'Opportunity', 'Threat');
$styles = array('Strength' => 'success', 'Weakness' => 'warning', 'Opportunity' => 'info', 'Threat' => 'danger');
$grouped = array();
foreach ((array) $entries as $entry) {
    $date = $entry->effectivity_date ?: $entry->applicable_year . '-01-01';
    if (!isset($grouped[$date])) $grouped[$date] = array_fill_keys($types, array());
    if (isset($grouped[$date][$entry->swot_type])) $grouped[$date][$entry->swot_type][] = $entry;
}
?>
