        <div class="card add-form mb-4"><div class="card-body"><h5 class="mb-3" id="formTitle">Add SWOT Entry</h5><form method="post" action="<?= base_url(); ?>Page/swot_save" id="swotForm"><input type="hidden" name="id" id="entryId"><div class="form-row"><div class="form-group col-md-2"><label>Year</label><input class="form-control" name="applicable_year" id="entryYear" value="<?= $esc($selectedYear); ?>" required></div><div class="form-group col-md-3"><label>Effectivity <span class="required">*</span></label><input class="form-control" type="date" name="effectivity_date" id="entryEffectivity" value="<?= $esc($selectedEffectivity ?: date('Y-m-d')); ?>" required></div><div class="form-group col-md-3"><label>Category <span class="required">*</span></label><select class="form-control" name="swot_type" id="entryType" required><option value="">Select category</option><?php foreach ($types as $type): ?><option value="<?= $type; ?>"><?= $type; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-4"><label>Description <span class="required">*</span></label><textarea class="form-control" rows="2" name="description" id="entryDescription" required placeholder="Enter the SWOT item"></textarea></div></div><button class="btn btn-primary" type="submit" id="saveButton"><i class="mdi mdi-content-save"></i> Save Entry</button> <button class="btn btn-light d-none" type="button" id="cancelEdit">Cancel edit</button></form></div></div>
        <?php if (empty($grouped)): ?><div class="alert alert-light border">No SWOT entries found for this filter.</div><?php endif; ?>
        <?php foreach ($grouped as $effectivity => $effectivityEntries): ?><h5 class="mb-3"><i class="mdi mdi-calendar-check-outline mr-1"></i>Effective <?= $esc(date('F j, Y', strtotime($effectivity))); ?></h5><div class="row"><?php foreach ($types as $type): $style = $styles[$type]; ?><div class="col-xl-3 col-md-6 mb-4"><div class="card swot-card"><div class="card-header bg-<?= $style; ?> <?= $style === 'warning' ? 'text-dark' : 'text-white'; ?>"><i class="mdi mdi-<?= $type === 'Strength' ? 'arm-flex-outline' : ($type === 'Weakness' ? 'alert-outline' : ($type === 'Opportunity' ? 'lightbulb-outline' : 'shield-alert-outline')); ?> mr-1"></i><?= $type; ?>s</div><div class="card-body"><?php if (empty($effectivityEntries[$type])): ?><p class="text-muted mb-0">No <?= strtolower($type); ?>s recorded.</p><?php else: foreach ($effectivityEntries[$type] as $entry): ?><div class="swot-entry"><span class="entry-actions"><button type="button" class="edit-entry" title="Edit" data-id="<?= (int)$entry->id; ?>" data-year="<?= $esc($entry->applicable_year); ?>" data-effectivity="<?= $esc($entry->effectivity_date); ?>" data-type="<?= $esc($entry->swot_type); ?>" data-description="<?= $esc($entry->description); ?>"><i class="mdi mdi-pencil"></i></button><form method="post" action="<?= base_url(); ?>Page/swot_delete" class="d-inline"><input type="hidden" name="id" value="<?= (int)$entry->id; ?>"><input type="hidden" name="applicable_year" value="<?= $esc($selectedYear); ?>"><input type="hidden" name="effectivity_date" value="<?= $esc($selectedEffectivity); ?>"><button class="delete" title="Delete" onclick="return confirm('Delete this SWOT entry?');"><i class="mdi mdi-delete"></i></button></form></span><?= $esc($entry->description); ?></div><?php endforeach; endif; ?></div></div></div><?php endforeach; ?></div><?php endforeach; ?>
